(function(root){const C=typeof module!=='undefined'?require('./crystal.js'):root.Crystal,clip=typeof module!=='undefined'?require('./vendor/polygon-clipping.min.js'):root.polygonClipping;
function inside(p,ring){let yes=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])yes=!yes}return yes}
function multi(loops){const outer=loops.filter(p=>C.area(p)>0),holes=loops.filter(p=>C.area(p)<0);return outer.map(p=>[p,...holes.filter(h=>inside(h[0],p)&&!outer.some(q=>q!==p&&Math.abs(C.area(q))<Math.abs(C.area(p))&&inside(h[0],q)))].map(r=>[...r,r[0]]))}
function enforce(loops,size,axis=0){if(!loops.length)return [];const c=size/2,r=size*3,wedge=[[[c,c],[c+r*Math.cos(axis),c+r*Math.sin(axis)],[c+r*Math.cos(axis+Math.PI/6),c+r*Math.sin(axis+Math.PI/6)],[c,c]]],half=clip.intersection(multi(loops),[wedge]);if(!half.length)return [];let pieces=[];for(let k=0;k<6;k++)for(const mirror of [false,true]){let co=Math.cos(k*Math.PI/3),si=Math.sin(k*Math.PI/3),ca=Math.cos(2*axis),sa=Math.sin(2*axis);pieces.push(half.map(p=>p.map(r=>r.map(([x,y])=>{x-=c;y-=c;if(mirror)[x,y]=[ca*x+sa*y,sa*x-ca*y];return [c+x*co-y*si,c+x*si+y*co]}))))}// The twelve sectors only meet at seams: cancel paired seam edges and stitch.
const edges=new Map(),pointKey=p=>p.map(v=>Math.round(v*1e6)/1e6).join(',');for(let index=0;index<pieces.length;index++)for(const polygon of pieces[index])for(const sourceRing of polygon){let ring=sourceRing.slice(0,-1);if(index%2===1)ring=ring.slice().reverse();for(let j=0;j<ring.length;j++){let a=pointKey(ring[j]),b=pointKey(ring[(j+1)%ring.length]);if(a===b)continue;let key=a+'|'+b,reverse=b+'|'+a;if(edges.has(reverse))edges.delete(reverse);else edges.set(key,[a,b])}}
const outgoing=new Map();for(const [key,[a,b]] of edges){if(!outgoing.has(a))outgoing.set(a,[]);outgoing.get(a).push([key,b])}const out=[];while(edges.size){const [initial,[start]]=edges.entries().next().value;let current=start,ring=[],guard=0;do{ring.push(current.split(',').map(Number));const next=outgoing.get(current)?.find(([key])=>edges.has(key));if(!next)throw Error('Could not close symmetric boundary');edges.delete(next[0]);current=next[1];if(++guard>100000)throw Error('Symmetric boundary too complex')}while(current!==start);if(ring.length>=3)out.push(ring)}return out}

function axis(mask,n){let x=0,y=0,c=n/2;for(let j=0;j<n;j++)for(let i=0;i<n;i++)if(mask[j*n+i]){let dx=i+.5-c,dy=j+.5-c,r=dx*dx+dy*dy,a=6*Math.atan2(dy,dx);x+=r*Math.cos(a);y+=r*Math.sin(a)}return Math.atan2(y,x)/6}
root.ExactSymmetry={enforce,multi,axis};if(typeof module!=='undefined')module.exports=root.ExactSymmetry;
})(globalThis);
